$expenses=is_array($expenses??null)?$expenses:[];
$settlements=is_array($settlements??null)?$settlements:[];
$error=is_string($error??null)?$error:'';
$csrf=is_string($csrf??null)?$csrf:'';
$escape=static fn(mixed $value):string=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$money=static fn(mixed $minor,mixed $precision):string=>number_format(((int)$minor)/(10**max(0,min(4,(int)$precision))),max(0,min(4,(int)$precision)),'.',',');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Model settlements · <?= $escape($brandName??'Talyvane') ?></title>
<style>
:root{color-scheme:light;--ink:#18212b;--muted:#64748b;--line:#dbe2e8;--paper:#f4f6f8;--accent:#245c50;--danger:#8b3535}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.55 system-ui,sans-serif}main{max-width:1240px;margin:30px auto;padding:0 18px}.panel,.record{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;margin:16px 0}.record{display:grid;grid-template-columns:minmax(190px,1fr) minmax(340px,2fr);gap:22px}.small{font-size:12px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.field{display:flex;flex-direction:column;gap:5px;margin:9px 0}.field label{font-weight:650;font-size:12px}.field input,.field select,.field textarea{border:1px solid var(--line);border-radius:7px;padding:9px;font:inherit;width:100%}.field textarea{min-height:70px}.button{background:var(--accent);color:white;border:0;border-radius:7px;padding:9px 13px;font-weight:650;cursor:pointer}.secondary{background:#e9eef0;color:var(--ink)}.actions{display:flex;flex-wrap:wrap;gap:10px}.actions form{min-width:220px;flex:1;border-top:1px solid var(--line);padding-top:10px}.error{background:#fff2f0;border:1px solid #f0c5bd;padding:12px;border-radius:8px}.empty{color:var(--muted);padding:14px;border:1px dashed var(--line);border-radius:8px}.claim{border:1px solid var(--line);border-radius:8px;padding:12px;margin:10px 0}.status{font-weight:700;text-transform:uppercase;letter-spacing:.05em;font-size:11px}.notice{background:#f5f7f8;border-left:3px solid #64748b;padding:12px;margin:12px 0}.section-title{margin-top:32px}@media(max-width:700px){.record{grid-template-columns:1fr}}
</style></head><body><main><h1>Model settlement and finance register</h1><p class="small">Role-gated finance operations. Amounts are stored in integer currency minor units and each settlement is recalculated before approval.</p>
<div class="notice"><strong>External payment only:</strong> This workspace records payment evidence supplied by an authorized operator. It does not initiate transfers, hold funds, provide escrow or custody, or store payment credentials.</div>
<?php if($error!==''):?><div class="error" role="alert"><?= $escape($error) ?></div><?php endif;?>
<section class="panel"><h2>Assignment expense review</h2>
<?php if($assignments===[]):?><div class="empty">No active or completed assignments are available to finance.</div><?php else:?>
<?php foreach($assignments as $assignment):?>
<article class="record"><div><strong><?= $escape($assignment['assignment_reference']) ?></strong><p class="status"><?= $escape($assignment['status']) ?></p><p class="small"><?= $escape($assignment['currency_code']??'No currency') ?> · compensation <?= $assignment['compensation_minor']===null?'not agreed':$money($assignment['compensation_minor'],$assignment['currency_precision']??2) ?> minor-unit precision snapshot pending · expense cap <?= $money($assignment['expense_cap_minor'],$assignment['currency_precision']??2) ?></p><p class="small"><?= $escape($assignment['shoot_starts_at']) ?> – <?= $escape($assignment['shoot_ends_at']) ?></p></div>
<div>
<?php $claims=$expenses[$assignment['id']]??[];?>
<?php if($claims===[]):?><div class="empty">No expense claims recorded.</div><?php else:?>
<?php foreach($claims as $claim):?><div class="claim"><strong><?= $escape($claim['currency_code']) ?> <?= $money($claim['amount_minor'],$assignment['currency_precision']??2) ?> · <span class="status"><?= $escape($claim['status']) ?></span></strong><p><?= $escape($claim['description']) ?></p><p class="small">Evidence reference: <?= $escape($claim['evidence_reference']??'Not supplied') ?> · Submitted by <?= $escape(substr((string)$claim['submitted_by'],0,8)) ?></p>
<?php if($claim['status']==='pending'):?><form method="post" action="/admin/model-agency/settlements/expenses/<?= $escape($claim['id']) ?>/review"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="grid"><div class="field"><label>Decision</label><select name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option></select></div><div class="field"><label>Review note (20–1,500 characters)</label><textarea name="review_note" minlength="20" maxlength="1500" required></textarea></div></div><button class="button" type="submit">Record independent review</button></form><?php endif;?>
</div><?php endforeach;?>
<?php endif;?>
<?php if(in_array($assignment['status'],['in_progress','completed'],true) && $assignment['settlement_id']===null):?><form method="post" action="/admin/model-agency/settlements/assignments/<?= $escape($assignment['id']) ?>/expenses"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="idempotency_key" value="<?= $escape($expenseIdempotencyKeys[$assignment['id']]??'') ?>"><h3>Submit expense claim</h3><div class="grid"><div class="field"><label>Amount</label><input name="amount" inputmode="decimal" pattern="(?:0|[1-9][0-9]{0,13})(?:\.[0-9]{1,4})?" required></div><div class="field"><label>Currency</label><input name="currency" maxlength="3" value="<?= $escape($assignment['currency_code']) ?>" required></div><div class="field"><label>Description</label><input name="description" minlength="12" maxlength="500" required></div><div class="field"><label>Private evidence reference</label><input name="evidence_reference" pattern="private/model-expenses/[A-Za-z0-9][A-Za-z0-9._/-]{10,180}" required></div></div><button class="button secondary" type="submit">Submit expense</button></form><?php endif;?>
<?php if($assignment['status']==='completed' && $assignment['settlement_id']===null):?><form method="post" action="/admin/model-agency/settlements/assignments/<?= $escape($assignment['id']) ?>/draft"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><button class="button" type="submit">Calculate settlement draft</button></form><?php endif;?>
<?php if($assignment['settlement_id']!==null):?><p class="small">Settlement: <?= $escape($assignment['settlement_status']) ?> · <?= $escape(substr((string)$assignment['settlement_id'],0,8)) ?></p><?php endif;?>
</div></article>
<?php endforeach;?><?php endif;?></section>
<section class="panel section-title"><h2>Settlement register</h2>
<?php if($settlements===[]):?><div class="empty">No settlement drafts have been created.</div><?php else:?>
<?php foreach($settlements as $settlement):?><article class="claim"><div class="grid"><div><strong><?= $escape($settlement['settlement_reference']) ?></strong><p class="status"><?= $escape($settlement['status']) ?></p></div><div><strong><?= $escape($settlement['currency_code']) ?> <?= $money($settlement['model_net_minor'],$settlement['currency_precision']) ?></strong><p class="small">Gross <?= $money($settlement['gross_minor'],$settlement['currency_precision']) ?> · commission <?= $money($settlement['commission_minor'],$settlement['currency_precision']) ?> · approved expenses <?= $money($settlement['approved_expenses_minor'],$settlement['currency_precision']) ?></p></div><div><p class="small">Created by <?= $escape(substr((string)$settlement['created_by'],0,8)) ?> · Approved by <?= $escape(substr((string)($settlement['approved_by']??''),0,8)) ?></p></div></div>
<div class="actions">
<?php if($settlement['status']==='draft'):?><form method="post" action="/admin/model-agency/settlements/<?= $escape($settlement['id']) ?>/approve"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><button class="button" type="submit">Approve independently</button></form><?php endif;?>
<?php if($settlement['status']==='approved'):?><form method="post" action="/admin/model-agency/settlements/<?= $escape($settlement['id']) ?>/payment"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="grid"><div class="field"><label>External payment method</label><select name="method"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="other_external">Other external</option></select></div><div class="field"><label>Payment reference</label><input name="payment_reference" maxlength="200" required></div><div class="field"><label>Payment evidence reference</label><input name="evidence_reference" pattern="private/model-settlements/[A-Za-z0-9][A-Za-z0-9._/-]{10,180}" required></div></div><button class="button" type="submit">Attest external payment</button></form><?php endif;?>
<?php if($settlement['status']==='paid'):?><form method="post" action="/admin/model-agency/settlements/<?= $escape($settlement['id']) ?>/reverse"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="field"><label>Reversal reason</label><textarea name="reason" minlength="20" maxlength="1500" required></textarea></div><div class="field"><label>External reversal evidence</label><input name="evidence_reference" pattern="private/model-settlements/[A-Za-z0-9][A-Za-z0-9._/-]{10,180}" required></div><button class="button secondary" type="submit">Record reversal</button></form><?php endif;?>
<?php if(in_array($settlement['status'],['draft','approved','paid'],true)):?><form method="post" action="/admin/model-agency/settlements/<?= $escape($settlement['id']) ?>/dispute"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="field"><label>Dispute reason</label><textarea name="reason" minlength="20" maxlength="1500" required></textarea></div><div class="field"><label>Dispute evidence</label><input name="evidence_reference" pattern="private/model-settlements/[A-Za-z0-9][A-Za-z0-9._/-]{10,180}" required></div><button class="button secondary" type="submit">Open dispute</button></form><?php endif;?>
</div></article><?php endforeach;?><?php endif;?></section></main></body></html>
